diff --git a/src/log.ts b/src/log.ts
index 4892c8b..1e8a7f6 100644
--- a/src/log.ts
+++ b/src/log.ts
@@ -1,3 +1,36 @@
+let buffer: string[] = [];
+let flushing = false;
+let flushScheduled = false;
+
+const flush = (): Promise<void> => {
+  if (buffer.length === 0 || flushing) return Promise.resolve();
+
+  flushing = true;
+  const lines = buffer.splice(0);
+
+  return new Promise((resolve) => {
+    process.stdout.write(lines.join(''), () => {
+      flushing = false;
+      resolve();
+    });
+  });
+};
+
+const scheduleFlush = (): void => {
+  if (!flushScheduled) {
+    flushScheduled = true;
+    setImmediate(() => {
+      flushScheduled = false;
+      flush();
+    });
+  }
+};
+
 export const log = (message: string): void => {
-  process.stdout.write(`${JSON.stringify({ message })}\n`);
+  buffer.push(`${JSON.stringify({ message })}\n`);
+  scheduleFlush();
+};
+
+export const flushLogs = (): Promise<void> => {
+  return flush();
 };
